const input = $input.first().json;
const files = input.files || [];
const query = [
  `Changed languages: ${(input.languages || []).join(', ')}`,
  `Changed files: ${(files.map((f) => typeof f === 'string' ? f : f.filename).filter(Boolean)).join(', ')}`,
  `Diff summary: ${input.diff_summary || files.map((f) => `${f.filename}: ${(f.patch || '').slice(0, 1000)}`).join('\n')}`
].join('\n');
return [{ json: { original: input, embedding_request: { model: $env.OLLAMA_EMBEDDING_MODEL || 'nomic-embed-text', prompt: query }, query } }];

const response = $input.first().json;
const unavailable = Boolean(response.error || response.message === 'Not found' || !Array.isArray(response.result));
if (unavailable) {
  return [{ json: { standards_available: false, standards_unavailable_reason: response.error?.message || response.message || 'Qdrant or Ollama retrieval failed', standards: [] } }];
}
const standards = response.result.map((r) => ({ standard_id: r.payload?.standard_id || null, title: r.payload?.title || null, category: r.payload?.category || null, technology: r.payload?.technology || null, source_file: r.payload?.source_file || null, version: r.payload?.version || null, score: r.score, content: r.payload?.content || '' }));
return [{ json: { standards_available: true, standards_count: standards.length, standards } }];
